import * as React from "react"

const storageKey = "tak7-language"
export const LanguageContext = React.createContext({
  locale: "en",
  setLocale: () => {},
})

export const LanguageProvider = ({ children }) => {
  const [locale, updateLocale] = React.useState("en")
  React.useEffect(() => {
    try {
      const saved = window.localStorage.getItem(storageKey)
      if (saved === "ja" || saved === "en") updateLocale(saved)
    } catch {
      // Language switching also works when browser storage is unavailable.
    }
  }, [])
  React.useEffect(() => {
    document.documentElement.lang = locale
  }, [locale])
  const setLocale = React.useCallback(value => {
    if (value !== "ja" && value !== "en") return
    updateLocale(value)
    try {
      window.localStorage.setItem(storageKey, value)
    } catch {}
  }, [])
  const value = React.useMemo(
    () => ({ locale, setLocale }),
    [locale, setLocale]
  )
  return (
    <LanguageContext.Provider value={value}>
      {children}
    </LanguageContext.Provider>
  )
}

export const useLanguage = () => {
  const { locale, setLocale } = React.useContext(LanguageContext)
  return { locale, setLocale, t: (ja, en) => (locale === "en" ? en : ja) }
}

export const wrapRootElement = ({ element }) => (
  <LanguageProvider>{element}</LanguageProvider>
)
